#include <iostream>
#include <cstdio>
#include <cmath>
#include <cstring>

#define mx 1000
#define mod 1000000007

using namespace std;

int len;

long long sum(int pos) {
    long long all = 0;
    int t = 0;
    for (int i = len - 1; i >= pos; i--) {
        long long tmp = static_cast<long long>(pow(2, t)) % mod;
        tmp *= tmp;
        all += tmp % mod;
        t++;
    }
    return all;
}

int main() {
    char str[mx];
    long long ans;
    while (cin >> str) {
        ans = 0;
        len = strlen(str);
        for (int i = len - 1; i >= 0; i--) {
            if (str[i] == '1') {
                ans += sum(i) % mod;
            } else if (str[i] == '0') {
                ans *= 2;
            }
        }
        cout << ans << endl;
    }
    return 0;
}

